<?php $pageHeading = PublicTheme::text($settings, 'agenda'); include __DIR__ . '/banner.php'; ?>
<section class="next-shell next-archive"><nav class="next-tabs" aria-label="<?= e($pageHeading) ?>"><a href="/agenda" <?= !$archive ? 'aria-current="page"' : '' ?>><?= e(PublicTheme::text($settings, 'upcoming')) ?></a><a href="/agenda?arsip=1" <?= $archive ? 'aria-current="page"' : '' ?>><?= e(PublicTheme::text($settings, 'archive')) ?></a><a href="/kalender-pendidikan"><?= e(PublicTheme::text($settings, 'calendar')) ?></a></nav><div class="next-agenda-timeline">
<?php foreach ($events as $event): ?><article class="next-timeline-event"><time datetime="<?= e($event['start_date']) ?>"><strong><?= e(date('d',strtotime($event['start_date']))) ?></strong><span><?= e(date('M Y',strtotime($event['start_date']))) ?></span></time><div><p class="next-byline"><?= e(AcademicCalendar::CATEGORIES[$event['category']] ?? $event['category']) ?></p><h2><a href="/agenda/<?= (int) $event['id'] ?>"><?= e($event['title']) ?></a></h2><p><?= e($event['location'] ?? '') ?></p><?php if (!empty($event['event_time'])): ?><p><?= e(substr($event['event_time'],0,5)) ?></p><?php endif; ?></div></article><?php endforeach; ?>
</div><?php if (!$events): ?><p class="next-empty"><?= e(PublicTheme::text($settings, 'empty')) ?></p><?php endif; ?><nav class="next-pagination" aria-label="<?= e($pageHeading) ?>"><?php if ($page > 1): ?><a href="/agenda?arsip=<?= (int) $archive ?>&amp;page=<?= $page-1 ?>" aria-label="Sebelumnya">←</a><?php endif; ?><span><?= (int) $page ?></span><?php if (count($events) === 12): ?><a href="/agenda?arsip=<?= (int) $archive ?>&amp;page=<?= $page+1 ?>" aria-label="Berikutnya">→</a><?php endif; ?></nav></section>
